import express from "express";
import path from "path";
import fs from "fs";

async function startServer() {
  const app = express();
  const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

  // API routes
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok" });
  });

  const isProduction = process.env.NODE_ENV === "production" || fs.existsSync(path.join(process.cwd(), 'server.cjs')) || fs.existsSync(path.join(process.cwd(), 'index.html'));

  // Vite middleware for development
  if (!isProduction) {
    const viteModule = await import("vite");
    const vite = await viteModule.createServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    const distIndex = path.join(distPath, 'index.html');
    const staticPath = fs.existsSync(distIndex) ? distPath : process.cwd();

    app.use(express.static(staticPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(staticPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on port ${PORT}`);
  });
}

startServer();
